import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';

const ResidentList = () => {
  const [residents, setResidents] = useState([]);

  useEffect(() => {
    fetchResidents();
  }, []);

  const fetchResidents = async () => {
    try {
      const response = await axios.get('http://localhost:5001/api/residents');
      setResidents(response.data);
    } catch (err) {
      console.error(err);
    }
  };

  const updateInOutStatus = async (id, status) => {
    try {
      await axios.put(`http://localhost:5001/api/residents/${id}`, { inOutStatus: status });
      fetchResidents();
    } catch (err) {
      console.error(err);
    }
  };

  const deleteResident = async (id) => {
    try {
      await axios.delete(`http://localhost:5001/api/residents/${id}`);
      fetchResidents();
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div>
      <Link to="/add-resident">
        <button className="add-btn">Add New Resident</button>
      </Link>
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Room Number</th>
            <th>In/Out Status</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {residents.map((resident) => (
            <tr key={resident._id}>
              <td>{resident.name}</td>
              <td>{resident.roomId ? resident.roomId.roomNumber : 'N/A'}</td>
              <td>{resident.inOutStatus}</td>
              <td>
                <button
                  className="update-btn"
                  onClick={() => updateInOutStatus(resident._id, resident.inOutStatus === 'In' ? 'Out' : 'In')}
                >
                  Toggle In/Out
                </button>
                <button
                  className="delete-btn"
                  onClick={() => deleteResident(resident._id)}
                >
                  Delete
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default ResidentList;
